// splash_logo.h - 1-bit splash screen logo (cisco_logo_240x120)
//
// FORMAT
//   - 1 bit per pixel, MSB-first (leftmost pixel = bit 7 of each byte)
//   - 1 = draw a pixel (any draw colour), 0 = leave unchanged
//   - Rows are padded to whole bytes: bytes_per_row = (width + 7) / 8 = 30,
//     so the array is 30 * 120 = 3600 bytes (240 is a multiple of 8, so
//     there are no padding bits).
//   - Needs C++ (constexpr, 0b literals).
//
// SIZE
//   240x120 px, the full design frame. The artwork has transparent margins
//   (about 6 px left/right), so position the whole bitmap, not the ink.
//   To centre on a screen of width SW, height SH: x0 = (SW - 240) / 2,
//   y0 = (SH - 120) / 2. Same format as icons_v4.h, so the same draw
//   routine works.

#pragma once
#include "bitmap.hh"
#include <stdint.h>

